/**
 * Mock implementation of the service contract. It behaves like the FastAPI backend: same entities,
 * same endpoints, asynchronous optimization with progress. Data starts from fixtures generated by
 * the Python core (scripts/build_mock_fixtures.py) and changes are kept in localStorage.
 */
import type { Api } from '../types';
import type {
  Destination,
  FleetConfig,
  ImportResult,
  Order,
  OrderLine,
  Product,
  Run,
  RunDetail,
  Scenario,
  ScenarioSummary,
} from '@/types/api';
import destinationsFixture from './fixtures/destinations.json';
import productsFixture from './fixtures/products.json';
import s1Fixture from './fixtures/scenario_s1.json';
import { generateOrders } from './generator';
import type { SolveRequest, SolveResult } from './solver/solve';
import type { WorkerMessage } from './solver/solver.worker';

const STORAGE_KEY = 'synaplogix.mock.v1';
const LATENCY_MS = 120;

interface GeneratedScenario {
  scenario: Scenario;
  params: { n_orders: number; mean_lines: number; max_units: number; seed: number };
}

interface ImportedScenario {
  scenario: Scenario;
  orders: Order[];
  order_lines: OrderLine[];
}

interface PersistedState {
  products: Product[] | null;
  destinations: Destination[] | null;
  generated: GeneratedScenario[];
  imported: ImportedScenario[];
  fleets: FleetConfig[];
  currentFleetId: string;
  runs: RunDetail[];
  counter: number;
}

const DEFAULT_FLEET: FleetConfig = {
  fleet_id: 'F001',
  capacity_units: 60_000,
  speed_kmh: 70,
  cost_per_km: 1.1,
  max_driving_hours: null,
};

function initialState(): PersistedState {
  return {
    products: null,
    destinations: null,
    generated: [],
    imported: [],
    fleets: [DEFAULT_FLEET],
    currentFleetId: DEFAULT_FLEET.fleet_id,
    runs: [],
    counter: 1,
  };
}

function load(): PersistedState {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) return { ...initialState(), ...JSON.parse(raw) };
  } catch {
    /* storage unavailable: start from the fixtures */
  }
  return initialState();
}

let state = load();
const running = new Map<string, RunDetail>();
/** Generated scenarios are rebuilt from their seed instead of being stored (they can hold 50,000 lines). */
const scenarioData = new Map<string, { orders: Order[]; order_lines: OrderLine[] }>();

function save(): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch {
    // Quota exceeded (large imported scenarios): keep imported data in memory only.
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...state, imported: [] }));
    } catch {
      /* storage unavailable */
    }
  }
}

const delay = <T>(value: T, ms = LATENCY_MS) =>
  new Promise<T>((resolve) => setTimeout(() => resolve(value), ms));
const clone = <T>(value: T): T => structuredClone(value);
const nowIso = () => new Date().toISOString().slice(0, 19);
const nextId = (prefix: string) => `${prefix}${String(state.counter++).padStart(4, '0')}`;

const products = () => state.products ?? (productsFixture as Product[]);
const destinations = () => state.destinations ?? (destinationsFixture as Destination[]);

const s1 = s1Fixture as { scenario: Scenario; orders: Order[]; order_lines: OrderLine[] };

function dataOf(scenarioId: string): { orders: Order[]; order_lines: OrderLine[] } {
  if (scenarioId === s1.scenario.scenario_id) return s1;
  const imported = state.imported.find((s) => s.scenario.scenario_id === scenarioId);
  if (imported) return imported;
  const generated = state.generated.find((s) => s.scenario.scenario_id === scenarioId);
  if (!generated) throw new Error(`Unknown scenario ${scenarioId}`);
  let data = scenarioData.get(scenarioId);
  if (!data) {
    const p = generated.params;
    data = generateOrders(
      scenarioId,
      p.n_orders,
      p.mean_lines,
      p.max_units,
      p.seed,
      destinations(),
      products(),
    );
    scenarioData.set(scenarioId, data);
  }
  return data;
}

function summarize(scenario: Scenario): ScenarioSummary {
  const { orders, order_lines } = dataOf(scenario.scenario_id);
  return {
    ...scenario,
    n_orders: orders.length,
    n_lines: order_lines.length,
    total_units: order_lines.reduce((sum, l) => sum + l.quantity, 0),
  };
}

function allScenarios(): Scenario[] {
  return [s1.scenario, ...state.generated.map((g) => g.scenario), ...state.imported.map((i) => i.scenario)];
}

/** Runs the solver in a Web Worker (or inline where workers do not exist, such as unit tests). */
function runSolver(request: SolveRequest, onProgress: (p: number) => void): Promise<SolveResult> {
  if (typeof Worker === 'undefined') {
    return import('./solver/solve').then(({ solve }) => solve(request, onProgress));
  }
  return new Promise((resolve, reject) => {
    const worker = new Worker(new URL('./solver/solver.worker.ts', import.meta.url), { type: 'module' });
    worker.onmessage = (event: MessageEvent<WorkerMessage>) => {
      const message = event.data;
      if (message.type === 'progress') onProgress(message.progress);
      else {
        worker.terminate();
        if (message.type === 'done') resolve(message.result);
        else reject(new Error(message.message));
      }
    };
    worker.onerror = (error) => {
      worker.terminate();
      reject(error);
    };
    worker.postMessage(request);
  });
}

const okImport = (dataset: ImportResult['dataset'], imported: number): ImportResult => ({
  dataset,
  imported,
  errors: [],
});

export const mockApi: Api = {
  products: {
    list: () => delay(clone(products())),
    import: (rows) => {
      state.products = rows;
      save();
      return delay(okImport('products', rows.length));
    },
  },
  destinations: {
    list: () => delay(clone(destinations())),
    import: (rows) => {
      // The depot is fixed: keep Mataró (D000) even if the file does not include it.
      const depot = destinations().find((d) => d.destination_id === 'D000')!;
      state.destinations = rows.some((r) => r.destination_id === 'D000') ? rows : [depot, ...rows];
      save();
      return delay(okImport('destinations', rows.length));
    },
  },
  orders: {
    list: (scenarioId) => delay(clone(dataOf(scenarioId).orders)),
    lines: (scenarioId) => delay(clone(dataOf(scenarioId).order_lines)),
    import: (request) => {
      const scenario: Scenario = {
        scenario_id: nextId('IMP'),
        name: request.scenario.name,
        type: request.scenario.type,
        seed: null,
        created_at: nowIso(),
      };
      const orders = request.orders.map((o) => ({ ...o, scenario_id: scenario.scenario_id }));
      state.imported.push({ scenario, orders, order_lines: request.order_lines });
      save();
      return delay({ ...okImport('orders', orders.length), scenario: summarize(scenario) });
    },
  },
  scenarios: {
    list: () => delay(allScenarios().map(summarize).reverse()),
    generate: (request) => {
      const scenario: Scenario = {
        scenario_id: nextId('GEN'),
        name: request.name,
        type: 'training',
        seed: request.seed,
        created_at: nowIso(),
      };
      state.generated.push({
        scenario,
        params: {
          n_orders: request.n_orders,
          mean_lines: request.mean_lines,
          max_units: request.max_units,
          seed: request.seed,
        },
      });
      save();
      return delay(summarize(scenario), 300);
    },
    remove: (scenarioId) => {
      state.generated = state.generated.filter((s) => s.scenario.scenario_id !== scenarioId);
      state.imported = state.imported.filter((s) => s.scenario.scenario_id !== scenarioId);
      scenarioData.delete(scenarioId);
      save();
      return delay(undefined);
    },
  },
  fleet: {
    list: () => delay(clone([...state.fleets].reverse())),
    current: () =>
      delay(clone(state.fleets.find((f) => f.fleet_id === state.currentFleetId) ?? DEFAULT_FLEET)),
    save: (config) => {
      const fleet: FleetConfig = {
        ...config,
        fleet_id: `F${String(state.fleets.length + 1).padStart(3, '0')}`,
      };
      state.fleets.push(fleet);
      state.currentFleetId = fleet.fleet_id;
      save();
      return delay(clone(fleet));
    },
  },
  optimize: {
    start: (request) => {
      const fleet = state.fleets.find((f) => f.fleet_id === request.fleet_id);
      const scenario = allScenarios().find((s) => s.scenario_id === request.scenario_id);
      if (!fleet || !scenario) return Promise.reject(new Error('not_found'));
      const runId = nextId('RUN');
      save();
      const run: Run = {
        run_id: runId,
        scenario_id: scenario.scenario_id,
        fleet_id: fleet.fleet_id,
        algorithm: request.algorithm,
        n_trucks: 0,
        total_km: 0,
        total_cost: 0,
        computation_time_s: 0,
        created_at: nowIso(),
      };
      const detail: RunDetail = {
        run,
        status: 'running',
        progress: 0,
        message: request.algorithm === 'ortools' ? 'mock_ortools' : 'approximate_distances',
        scenario_name: scenario.name,
        fleet,
        kpis: null,
        routes: [],
        stops: [],
        infeasible: [],
      };
      running.set(runId, detail);
      const { orders, order_lines } = dataOf(scenario.scenario_id);
      runSolver(
        {
          run_id: runId,
          algorithm: request.algorithm,
          time_limit_s: request.time_limit_s,
          seed: scenario.seed ?? 1,
          orders,
          lines: order_lines,
          products: products(),
          destinations: destinations(),
          fleet,
        },
        (progress) => {
          detail.progress = progress;
        },
      )
        .then((result) => {
          const done: RunDetail = {
            ...detail,
            status: 'done',
            progress: 1,
            run: {
              ...run,
              n_trucks: result.n_trucks,
              total_km: result.total_km,
              total_cost: result.total_cost,
              computation_time_s: result.computation_time_s,
            },
            kpis: result.kpis,
            routes: result.routes,
            stops: result.stops,
            infeasible: result.infeasible,
            validation_errors: result.validation_errors,
          };
          running.delete(runId);
          state.runs.push(done);
          save();
        })
        .catch(() => {
          detail.status = 'failed';
        });
      return delay({ run_id: runId, status: 'running' as const }, 50);
    },
  },
  results: {
    list: () => delay(state.runs.map((r) => clone(r.run)).reverse()),
    get: (runId) => {
      const detail = running.get(runId) ?? state.runs.find((r) => r.run.run_id === runId);
      return detail ? delay(clone(detail), 40) : Promise.reject(new Error('not_found'));
    },
    remove: (runId) => {
      state.runs = state.runs.filter((r) => r.run.run_id !== runId);
      save();
      return delay(undefined);
    },
  },
};

/** Test helper: forget every change and go back to the fixtures. */
export function resetMockState(): void {
  state = initialState();
  running.clear();
  scenarioData.clear();
  save();
}
